  const [duration, setDuration] = useState(0);
  const [isExpanded, setIsExpanded] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const timerRef = useRef<number | null>(null);
  const syncTimerRef = useRef<number | null>(null);

  // Format seconds to MM:SS
  const formatTime = (secs: number) => {
    const m = Math.floor(secs / 60);
    const s = secs % 60;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const handleToggleRecord = async () => {
    if (isRecording) {
      handleStop();
    } else {
      setErrorMsg(null);
      try {
        await recordingService.startRecording(mode);
        setIsRecording(true);
        setDuration(0);

        // Start Duration Timer
        timerRef.current = window.setInterval(() => {
          setDuration(prev => prev + 1);
        }, 1000);

        // Start Safety Sync Timer (checks if browser stopped sharing externally via system UI)
        syncTimerRef.current = window.setInterval(() => {
            if (!recordingService.isRecording) {
                handleStop();
            }
        }, 1000);

      } catch (e: any) {
        // Determine user-friendly error message
        let msg = "Capture Failed";

        // Check for specific error types
        const isNotAllowed = e.name === 'NotAllowedError' || e.name === 'PermissionDeniedError';
        const isUserCancel = e.message && (e.message.includes("denied by user") || e.message.includes("Permission denied"));
        const isPolicy = e.message && e.message.includes("permissions policy");

        if (isNotAllowed) {
            if (isUserCancel) {
                msg = "Cancelled"; // User clicked "Cancel" on dialog
            } else {
                msg = "Permission Denied"; // Browser blocked it
            }
        } else if (isPolicy) {
            msg = "Policy Restriction";
        } else if (e.name === 'NotFoundError') {
            msg = "No Device Found";
        } else if (e.name === 'NotReadableError') {
            msg = "Hardware Error";
        }

        // Only log actual failures, not user cancellations
        if (msg !== "Cancelled") {
            console.error("Recording Error:", e);
        }

        setErrorMsg(msg);
        setTimeout(() => setErrorMsg(null), 3000);
      }
    }
  };

  const handleStop = () => {
    recordingService.stopRecording();
    setIsRecording(false);

    if (timerRef.current) {
        clearInterval(timerRef.current);
        timerRef.current = null;
    }
    if (syncTimerRef.current) {
        clearInterval(syncTimerRef.current);
        syncTimerRef.current = null;
    }
  };

